cd /workspace && python3 - <<'EOF'
from pptx import Presentation
p = Presentation('inputs/materials/conv_fa46a4502e37/2021哈工大机器人智能护理床BP.pptx')
for idx in [2,3,26,27,28,33,34,36,37,38]:
    s = p.slides[idx]
    print(f'===== slide {idx+1} =====')
    def walk(shapes):
        for sh in shapes:
            if sh.shape_type == 6:
                walk(sh.shapes); continue
            if sh.has_text_frame and sh.text_frame.text.strip():
                print(f'--[{sh.name}]--')
                for para in sh.text_frame.paragraphs:
                    print('  |', ''.join(r.text for r in para.runs))
            if sh.has_table if hasattr(sh,'has_table') else False:
                print(f'--TABLE {sh.name}--')
                for row in sh.table.rows:
                    print('  ROW:', [c.text.replace(chr(10),' / ')[:40] for c in row.cells])
    walk(s.shapes)
EOF
